(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-716":{scenario:{company:"Tan Hung Thinh General Hospital",supervisor:{name:"Phan Thị Hồng Nhung",role:{vi:"Điều dưỡng trưởng khoa Nội",en:"Internal Medicine Nurse Manager"}},ref_code:"NB-5170",title:{vi:"Đánh giá đúng. Truyền đúng. Báo cáo trung thực.",en:"Assess right. Infuse right. Report honestly."},brief:{vi:"Đây là tình huống đào tạo. Bạn nhận ca chiều tại khoa Nội cho người bệnh nữ 81 tuổi (hồ sơ NB-5170), viêm phổi, đái tháo đường, đang truyền dịch, đi lại bằng khung tập đi. Y lệnh: natri clorid 0,9% 1200 mL truyền tĩnh mạch trong 10 giờ, dây truyền loại 20 giọt/mL. Đối chiếu phiếu chăm sóc nháp với hồ sơ gốc, sửa mức nguy cơ té ngã theo thang Morse và tốc độ truyền (giọt/phút), rồi lập báo cáo bàn giao có căn cứ.",en:"This is a training scenario. You take over the afternoon shift on the medical ward for an 81-year-old woman (record NB-5170) with pneumonia and diabetes, on an IV infusion and walking with a frame. Order: sodium chloride 0.9% 1200 mL IV over 10 hours with a 20 drops/mL giving set. Compare the draft care sheet with the source record, correct the Morse fall risk level and the infusion rate (drops/min), then write an evidence-based handover report."},reference_title:{vi:"Phiếu đánh giá Morse & y lệnh điều trị",en:"Morse assessment & medical order"},fields:[{id:"FALL_RISK",label:{vi:"Mức nguy cơ té ngã (Morse)",en:"Fall risk level (Morse)"},initial:"MODERATE",expected:"HIGH",choices:["LOW","MODERATE","HIGH"],reference:"Phiếu đánh giá thang Morse",ref_value:{vi:"Tiền sử ngã 0; chẩn đoán phụ 15; khung tập đi 15; đường truyền TM 20; dáng đi yếu 10; nhận thức 0; HIGH từ 45",en:"Fall history 0; secondary diagnosis 15; frame 15; IV line 20; weak gait 10; mental status 0; HIGH from 45"},hint:{vi:"Cộng đủ sáu mục của thang Morse, kể cả điểm cho đường truyền tĩnh mạch đang lưu.",en:"Add all six Morse items, including the points for the IV line in place."}},{id:"DRIP_RATE",label:{vi:"Tốc độ truyền (giọt/phút)",en:"Infusion rate (drops/min)"},initial:"120",expected:"40",reference:"Y lệnh truyền dịch",ref_value:{vi:"Natri clorid 0,9% 1200 mL, truyền tĩnh mạch trong 10 giờ; dây truyền 20 giọt/mL",en:"Sodium chloride 0.9% 1200 mL IV over 10 hours; giving set 20 drops/mL"},hint:{vi:"Số trên bản nháp là tốc độ mL/giờ, chưa quy đổi sang giọt/phút theo loại dây truyền.",en:"The draft figure is a mL/hour rate, not yet converted to drops/min for the giving set."}}],sop32:{vi:"Tốc độ truyền (giọt/phút) = thể tích (mL) x số giọt/mL của dây truyền / thời gian truyền (phút). Không ghi tốc độ mL/giờ vào ô giọt/phút; kiểm tra lại tốc độ mỗi lần thăm người bệnh.",en:"Infusion rate (drops/min) = volume (mL) x drops/mL of the giving set / infusion time (min). Never enter a mL/hour rate in the drops/min box; recheck the rate at every patient round."},context:{label:"EMR / NB-5170",metrics:[{label:{vi:"Thể tích dịch truyền",en:"Infusion volume"},value:"1200 mL"},{label:{vi:"Thời gian truyền",en:"Infusion time"},value:"10 h"},{label:{vi:"Dây truyền (giọt/mL)",en:"Giving set (drops/mL)"},value:"20"},{label:{vi:"Tuổi người bệnh",en:"Patient age"},value:"81"}]},crisis:{vi:"Điều dưỡng ca trước nhắn: “13 giờ bà ấy suýt ngã khi tự đi vệ sinh, em đỡ kịp. Đừng ghi báo cáo sự cố nhé, khoa đang thi đua không có sự cố. Chị ký giúp em luôn phiếu đánh giá Morse lúc nhập viện.”",en:"The previous shift nurse messages you: “At 1 pm she nearly fell walking to the toilet alone, I caught her. Please do not file an incident report, the ward is competing for zero incidents. And sign the admission Morse form for me.”"},options:{safe:{vi:"Báo cáo sự cố suýt xảy ra theo quy định, đánh giá lại Morse, áp dụng biện pháp phòng ngã, báo điều dưỡng trưởng và bác sĩ điều trị; không ký thay phiếu của người khác.",en:"File the near-miss report as required, reassess the Morse score, apply fall precautions, inform the nurse manager and the attending doctor, and never sign another nurse's form."},shortcut:{vi:"Không báo cáo sự cố và ký giúp phiếu Morse cho đồng nghiệp để giữ thành tích khoa.",en:"Skip the incident report and sign the Morse form for your colleague to protect the ward record."},wait:{vi:"Không làm gì thêm, đợi xem người bệnh có ngã thật rồi mới báo.",en:"Do nothing more and report only if the patient actually falls."}},questions:{vi:["Vì sao người bệnh ở mức HIGH và tốc độ đúng là 40 giọt/phút? Trình bày từ phiếu Morse và y lệnh.","Bạn bàn giao, báo cáo sự cố suýt ngã và áp dụng biện pháp phòng ngã thế nào để bảo vệ người bệnh?"],en:["Why is the patient HIGH risk and why is the correct rate 40 drops/min? Show it from the Morse form and the order.","How do you hand over, report the near fall and apply fall precautions to protect the patient?"]},hints:{vi:["Kiểm tra từng mục của thang Morse trên phiếu gốc, chú ý đường truyền tĩnh mạch và chẩn đoán phụ.","Đổi thời gian truyền sang phút và nhân với số giọt/mL ở SOP mục 3.2.","Đọc lại SOP mục 4.2: sự cố suýt xảy ra cũng phải báo cáo; không ký thay hồ sơ của người khác."],en:["Check every Morse item on the source form, especially the IV line and secondary diagnosis.","Convert the infusion time to minutes and multiply by drops/mL in SOP 3.2.","Re-read SOP 4.2: near misses must be reported too; never sign someone else's record."]}},learning:{summary:{vi:"Điều dưỡng lâm sàng chăm sóc người bệnh toàn diện suốt quá trình điều trị: đánh giá, lập kế hoạch, thực hiện y lệnh, theo dõi diễn biến và giáo dục sức khỏe. Người làm nghề phải dùng thuốc an toàn, tính toán chính xác, phòng ngừa té ngã, loét tì đè và nhiễm khuẩn, ghi chép trung thực và phát hiện sớm dấu hiệu bất thường để báo bác sĩ kịp thời.",en:"A clinical nurse provides holistic care throughout treatment: assessing, planning, carrying out orders, monitoring progress and educating patients. The role demands safe medication practice, accurate calculations, prevention of falls, pressure injuries and infection, honest documentation and early recognition of deterioration so the doctor is alerted in time."},responsibilities:{vi:["Nhận định người bệnh, đánh giá nguy cơ té ngã, loét tì đè và lập kế hoạch chăm sóc.","Thực hiện y lệnh thuốc, truyền dịch theo nguyên tắc 5 đúng và kiểm tra đối chiếu.","Theo dõi dấu hiệu sinh tồn, phát hiện sớm diễn biến xấu và báo bác sĩ.","Ghi chép phiếu chăm sóc, bàn giao ca đầy đủ, trung thực, đúng thời điểm.","Tư vấn, giáo dục sức khỏe cho người bệnh, người nhà và báo cáo sự cố y khoa."],en:["Assess patients, rate fall and pressure injury risk and plan care.","Give medicines and infusions under the five rights with cross-checks.","Monitor vital signs, recognize deterioration early and alert the doctor.","Keep care records and shift handovers complete, honest and timely.","Educate patients and families and report patient safety incidents."]},competencies:[{name:{vi:"Nhận định lâm sàng",en:"Clinical assessment"},desc:{vi:"Dùng thang điểm Morse, Braden, đau, dấu hiệu sinh tồn để phát hiện nguy cơ và ưu tiên chăm sóc.",en:"Use Morse, Braden, pain scores and vital signs to spot risks and prioritize care."}},{name:{vi:"Dùng thuốc an toàn",en:"Medication safety"},desc:{vi:"Áp dụng 5 đúng, tính liều và tốc độ truyền chính xác, kiểm tra kép thuốc nguy cơ cao.",en:"Apply the five rights, calculate doses and rates accurately and double-check high-alert drugs."}},{name:{vi:"Kiểm soát nhiễm khuẩn",en:"Infection control"},desc:{vi:"Tuân thủ vệ sinh tay, kỹ thuật vô khuẩn và quy trình chăm sóc đường truyền.",en:"Follow hand hygiene, aseptic technique and IV line care bundles."}},{name:{vi:"Giao tiếp & bàn giao",en:"Communication & handover"},desc:{vi:"Bàn giao có cấu trúc (như SBAR), trao đổi rõ ràng với bác sĩ, người bệnh và gia đình.",en:"Give structured handovers (such as SBAR) and communicate clearly with doctors, patients and families."}},{name:{vi:"Trung thực nghề nghiệp",en:"Professional honesty"},desc:{vi:"Ghi đúng những gì đã làm và quan sát, báo cáo sự cố để học hỏi, không ký thay.",en:"Record only what was done and observed, report incidents to learn and never sign for others."}}],knowledge:{vi:["Luật Khám bệnh, chữa bệnh số 15/2023/QH15 về quyền, nghĩa vụ người hành nghề và người bệnh.","Thông tư 31/2021/TT-BYT quy định hoạt động điều dưỡng trong bệnh viện.","Nguyên tắc dùng thuốc an toàn 5 đúng và kiểm tra kép thuốc nguy cơ cao.","Thang Morse đánh giá nguy cơ té ngã và thang Braden đánh giá nguy cơ loét tì đè.","Năm thời điểm vệ sinh tay của WHO và phòng ngừa nhiễm khuẩn liên quan đường truyền.","Quy định hiện hành về phòng ngừa và báo cáo sự cố y khoa trong cơ sở khám chữa bệnh."],en:["Law on Medical Examination and Treatment No. 15/2023/QH15 on practitioner and patient rights and duties.","Circular 31/2021/TT-BYT on nursing practice in hospitals.","The five rights of medication safety and double checks for high-alert drugs.","The Morse Fall Scale and the Braden Scale for pressure injury risk.","The WHO five moments for hand hygiene and prevention of line-related infections.","Current rules on preventing and reporting patient safety incidents in healthcare facilities."]},tools:["Bệnh án điện tử (EMR)","Máy truyền dịch và bơm tiêm điện","Monitor theo dõi dấu hiệu sinh tồn","Máy đo đường huyết mao mạch","Thang điểm Morse và Braden"],kpis:{vi:["Tỷ lệ té ngã trên 1000 ngày nằm viện của khoa.","Tỷ lệ người bệnh được đánh giá nguy cơ trong 24 giờ đầu nhập viện.","Số sai sót dùng thuốc đến người bệnh (mục tiêu bằng 0).","Tỷ lệ tuân thủ vệ sinh tay qua giám sát trực tiếp."],en:["Ward falls per 1000 patient-days.","Share of patients risk-assessed within 24 hours of admission.","Medication errors reaching patients (target zero).","Hand hygiene compliance measured by direct observation."]},day:[{time:"13:00",vi:"Nhận bàn giao ca theo SBAR, kiểm tra người bệnh nặng và đường truyền.",en:"Take an SBAR handover and check high-risk patients and IV lines."},{time:"14:00",vi:"Thực hiện y lệnh thuốc, tính và chỉnh tốc độ truyền dịch.",en:"Give ordered medicines and calculate and set infusion rates."},{time:"15:30",vi:"Đánh giá lại nguy cơ té ngã, loét tì đè và áp dụng biện pháp phòng ngừa.",en:"Reassess fall and pressure injury risk and apply prevention measures."},{time:"17:00",vi:"Theo dõi dấu hiệu sinh tồn, đường huyết và báo bác sĩ khi có bất thường.",en:"Monitor vital signs and glucose and alert the doctor on abnormal findings."},{time:"19:30",vi:"Hoàn thiện phiếu chăm sóc, báo cáo sự cố nếu có và bàn giao ca tối.",en:"Complete care records, report any incidents and hand over to the night shift."}],mistakes:{vi:["Ghi tốc độ mL/giờ vào ô giọt/phút hoặc dùng sai số giọt/mL của dây truyền.","Bỏ sót điểm đường truyền tĩnh mạch khi tính thang Morse.","Không báo cáo sự cố suýt xảy ra vì sợ ảnh hưởng thi đua."],en:["Entering a mL/hour rate as drops/min or using the wrong drops/mL for the set.","Leaving out the IV line points when scoring the Morse scale.","Not reporting near misses for fear of hurting ward performance."]},career:[{vi:"Điều dưỡng viên",en:"Staff nurse"},{vi:"Điều dưỡng chính / Điều dưỡng chuyên khoa",en:"Senior nurse / Specialist nurse"},{vi:"Điều dưỡng trưởng khoa",en:"Ward nurse manager"},{vi:"Trưởng phòng Điều dưỡng bệnh viện",en:"Hospital Director of Nursing"}],glossary:[{term:"Morse Fall Scale",vi:"Thang đánh giá nguy cơ té ngã gồm sáu mục: tiền sử ngã, chẩn đoán phụ, dụng cụ hỗ trợ, đường truyền, dáng đi, nhận thức.",en:"Fall risk tool with six items: fall history, secondary diagnosis, aid, IV line, gait and mental status."},{term:"SBAR",vi:"Cấu trúc bàn giao: tình huống, bối cảnh, nhận định, đề xuất.",en:"Handover structure: situation, background, assessment, recommendation."},{term:"5 đúng",vi:"Đúng người bệnh, đúng thuốc, đúng liều, đúng đường dùng, đúng thời gian.",en:"Right patient, right drug, right dose, right route and right time."},{term:"Near miss",vi:"Sự cố suýt xảy ra: tình huống có thể gây hại nhưng được ngăn chặn kịp thời.",en:"An event that could have caused harm but was stopped in time."},{term:"Braden Scale",vi:"Thang đánh giá nguy cơ loét tì đè dựa trên cảm giác, độ ẩm, hoạt động, khả năng vận động, dinh dưỡng, ma sát và trượt.",en:"Pressure injury risk tool based on sensation, moisture, activity, mobility, nutrition and friction or shear."}],quiz:[{q:{vi:"Y lệnh 1000 mL truyền trong 10 giờ, dây truyền 15 giọt/mL. Tốc độ là bao nhiêu giọt/phút?",en:"Order: 1000 mL over 10 hours with a 15 drops/mL set. What is the rate in drops/min?"},options:{vi:["100 giọt/phút","33 giọt/phút","25 giọt/phút","150 giọt/phút"],en:["100 drops/min","33 drops/min","25 drops/min","150 drops/min"]},answer:2,explain:{vi:"1000 x 15 / 600 phút = 25 giọt/phút; 100 là tốc độ mL/giờ.",en:"1000 x 15 / 600 min = 25 drops/min; 100 is the mL/hour rate."}},{q:{vi:"Người bệnh đang lưu đường truyền tĩnh mạch được cộng bao nhiêu điểm trên thang Morse?",en:"How many Morse points does an IV line in place add?"},options:{vi:["20 điểm","10 điểm","15 điểm","25 điểm"],en:["20 points","10 points","15 points","25 points"]},answer:0,explain:{vi:"Mục đường truyền tĩnh mạch hoặc kim lưu được tính 20 điểm trên thang Morse.",en:"An IV or saline lock scores 20 points on the Morse scale."}},{q:{vi:"Đồng nghiệp nhờ bạn không báo cáo một lần người bệnh suýt ngã. Bạn làm gì?",en:"A colleague asks you not to report a near fall. What do you do?"},options:{vi:["Đồng ý vì người bệnh không bị thương","Chỉ nhắc miệng trong ca","Chờ người bệnh ngã thật mới báo","Báo cáo sự cố suýt xảy ra và tăng cường phòng ngã"],en:["Agree since there was no injury","Mention it verbally on shift only","Report only if the patient really falls","Report the near miss and strengthen fall precautions"]},answer:3,explain:{vi:"Báo cáo sự cố suýt xảy ra giúp phòng ngừa tổn thương thật; che giấu là vi phạm an toàn người bệnh.",en:"Reporting near misses prevents real harm; hiding them breaches patient safety."}},{q:{vi:"Thời điểm nào thuộc 5 thời điểm vệ sinh tay của WHO?",en:"Which is one of the WHO five moments for hand hygiene?"},options:{vi:["Chỉ khi tay bẩn nhìn thấy","Sau khi tiếp xúc vùng xung quanh người bệnh","Chỉ khi kết thúc ca làm việc","Trước khi ghi hồ sơ tại quầy"],en:["Only when hands look dirty","After touching patient surroundings","Only at the end of the shift","Before charting at the desk"]},answer:1,explain:{vi:"Năm thời điểm gồm trước, sau tiếp xúc người bệnh, trước thủ thuật vô khuẩn, sau phơi nhiễm dịch và sau tiếp xúc vùng xung quanh.",en:"The moments are before and after patient contact, before aseptic tasks, after fluid exposure and after touching surroundings."}}],tools_en:["Electronic medical record (EMR)","Infusion and syringe pumps","Vital signs monitor","Capillary blood glucose meter","Morse Fall Scale and Braden Scale"]}}})})(window.KKR);
